package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.AnnotatedWithParams;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.TypeBindings;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_verifyNonDup_TriageGen2Test {

    private CreatorCollector creatorCollector;
    private BeanDescription mockBeanDesc;
    private AnnotatedWithParams mockNewOne;
    private AnnotatedWithParams mockOldOne;

    @Before
    public void setUp() throws Exception {
        mockBeanDesc = mock(BeanDescription.class);
        creatorCollector = new CreatorCollector(mockBeanDesc, true);
        mockNewOne = mock(AnnotatedWithParams.class);
        mockOldOne = mock(AnnotatedWithParams.class);
    }

    /**
     * Helper to access protected method via reflection since it is protected 
     * and we are testing the logic within the package.
     */
    private void invokeVerifyNonDup(AnnotatedWithParams newOne, int typeIndex, boolean explicit) throws Exception {
        java.lang.reflect.Method method = CreatorCollector.class.getDeclaredMethod("verifyNonDup", AnnotatedWithParams.class, int.class, boolean.class);
        method.setAccessible(true);
        method.invoke(creatorCollector, newOne, typeIndex, explicit);
    }

    /**
     * Helper to set the private _creators array field for testing
     */
    private void setCreatorsArray(AnnotatedWithParams[] creators) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField("_creators");
        field.setAccessible(true);
        field.set(creatorCollector, creators);
    }

    /**
     * Helper to get the private _creators array field
     */
    private AnnotatedWithParams[] getCreatorsArray() throws Exception {
        Field field = CreatorCollector.class.getDeclaredField("_creators");
        field.setAccessible(true);
        return (AnnotatedWithParams[]) field.get(creatorCollector);
    }

    /**
     * Helper to get the private _explicitCreators bitmask
     */
    private int getExplicitCreators() throws Exception {
        Field field = CreatorCollector.class.getDeclaredField("_explicitCreators");
        field.setAccessible(true);
        return (int) field.get(creatorCollector);
    }

    /**
     * Helper to set the private _explicitCreators bitmask
     */
    private void setExplicitCreators(int value) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField("_explicitCreators");
        field.setAccessible(true);
        field.set(creatorCollector, value);
    }

    @Test
    public void testVerifyNonDup_FirstTime() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[10]);

        invokeVerifyNonDup(mockNewOne, typeIndex, true);

        assertTrue("Should set _hasNonDefaultCreator to true", creatorCollector.hasDefaultCreator());
        assertEquals("New creator should be stored", mockNewOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit bit should be set", (1 << typeIndex), getExplicitCreators());
    }

    @Test
    public void testVerifyNonDup_FirstTime_NotExplicit() throws Exception {
        int typeIndex = 1;
        setCreatorsArray(new AnnotatedWithParams[10]);

        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        assertEquals("New creator should be stored", mockNewOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit bit should NOT be set", 0, getExplicitCreators());
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsNotExplicit_ReturnEarly() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[]{mockOldOne});
        setExplicitCreators(1 << typeIndex); // Already has explicit bit

        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        // If it returns early, the creator array remains the old one
        assertEquals("Should have returned early without updating creator", mockOldOne, getCreatorsArray()[typeIndex]);
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsExplicit_ProceedToVerify() throws Exception {
        int typeIndex = 0;
        // Use different classes to avoid IllegalArgumentException branch
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);

        setCreatorsArray(new AnnotatedWithParams[]{oldOne});
        setExplicitCreators(1 << typeIndex);

        // This should NOT throw exception because classes are different
        invokeVerifyNonDup(newOne, typeIndex, true);

        assertEquals("Should update to new creator", newOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit bit should remain set", (1 << typeIndex), getExplicitCreators());
    }

    @Test(expected = Exception.class) // Reflection wraps IllegalArgumentException in InvocationTargetException
    public void testVerifyNonDup_ConflictSameClass_ThrowsException() throws Exception {
        int typeIndex = 0;
        // To trigger exception, oldOne.getClass() == newOne.getClass()
        // Since they are both mocks of AnnotatedWithParams, they have the same class
        setCreatorsArray(new AnnotatedWithParams[]{mockOldOne});

        invokeVerifyNonDup(mockNewOne, typeIndex, true);
    }

    @Test
    public void testVerifyNonDup_NoExplicitBit_DifferentClasses_Updates() throws Exception {
        int typeIndex = 2;
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);

        setCreatorsArray(new AnnotatedWithParams[10]);
        getCreatorsArray()[typeIndex] = oldOne;
        setExplicitCreators(0);

        invokeVerifyNonDup(newOne, typeIndex, true);

        assertEquals("Should update creator when no explicit bit was set", newOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit bit should be set", (1 << typeIndex), getExplicitCreators());
    }

    @Test
    public void testVerifyNonDup_NoExplicitBit_DifferentClasses_NoExplicitFlag() throws Exception {
        int typeIndex = 2;
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);

        setCreatorsArray(new AnnotatedWithParams[10]);
        getCreatorsArray()[typeIndex] = oldOne;
        setExplicitCreators(0);

        invokeVerifyNonDup(newOne, typeIndex, false);

        assertEquals("Should update creator", newOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit bit should remain 0", 0, getExplicitCreators());
    }
}
